{"explanation":"Start with a unit square (area 1). Fill half of it (1/2), then half of what's left (1/4), then half of the remainder (1/8), and so on. Each step covers half of the remaining empty space, so the uncovered area shrinks toward zero and the filled pieces add up to the whole square: 1/2 + 1/4 + 1/8 + ... = 1. Use the slider to add more pieces and watch the gap shrink.","manimCode":"const S = 4;
const x0 = -2, y0 = -2.2; // bottom-left of square
const outline = new Square({ sideLength: S, color: WHITE });
outline.moveTo([0, y0 + S/2, 0]);
scene.add(outline);

const title = new MathTex({ latex: '\\tfrac12+\\tfrac14+\\tfrac18+\\cdots=1' });
await title.waitForRender();
title.moveTo([0, 3.5, 0]);
scene.add(title);

const colors = [BLUE, TEAL, GREEN, YELLOW, ORANGE, RED, PURPLE, MAROON];
// Build pieces: alternate vertical/horizontal splits
let rx = x0, ry = y0, rw = S, rh = S; // remaining region
const pieces = [];
for (let i = 0; i < 8; i++) {
  let px, py, pw, ph;
  if (i % 2 === 0) { // take left half of the remaining width
    pw = rw / 2; ph = rh; px = rx; py = ry;
    rx += pw; rw -= pw;
  } else { // take bottom half of remaining height
    pw = rw; ph = rh / 2; px = rx; py = ry;
    ry += ph; rh -= ph;
  }
  const r = new Rectangle({ width: pw, height: ph, color: colors[i] });
  r.setFill(colors[i], 0.7);
  r.setStrokeWidth(1);
  r.moveTo([px + pw/2, py + ph/2, 0]);
  pieces.push(r);
}

const fracs = ['1/2','1/4','1/8','1/16','1/32','1/64','1/128','1/256'];
let label = null;
let shown = 0;
function setLabel(n) {
  if (label) scene.remove(label);
  const total = 1 - Math.pow(0.5, n);
  label = new Text({ text: n === 0 ? 'Sum so far: 0' : 'Sum so far: ' + (Math.pow(2,n)-1) + '/' + Math.pow(2,n) + ' ≈ ' + total.toFixed(4), color: WHITE, fontSize: 28 });
  label.moveTo([0, -3.3, 0]);
  scene.add(label);
}
setLabel(0);

for (let i = 0; i < 4; i++) {
  await scene.play(new FadeIn(pieces[i]));
  const t = new Text({ text: fracs[i], color: WHITE, fontSize: 22 });
  const c = pieces[i].getCenter();
  t.moveTo(c);
  if (i < 3) scene.add(t);
  shown = i + 1;
  setLabel(shown);
  await scene.wait(0.5);
}

const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({ label: 'Pieces', min: 0, max: 8, value: 4, step: 1, onChange: (v) => {
  for (let i = 0; i < 8; i++) {
    if (i < v) scene.add(pieces[i]); else scene.remove(pieces[i]);
  }
  setLabel(v);
}});

await scene.wait(999999);"}

